        t.real++;
        if (c.conclusion && RED_CONCLUSIONS.indexOf(c.conclusion) !== -1) t.red++;
        else if (!c.conclusion || PENDING_STATUSES.indexOf(c.status) !== -1) t.pending++;
    }
    return t;
