// null. A failed/absent status probe (pr === null) is NEVER counted
// (fail closed).
function _deadZoneRollup(pr) {
    if (!pr) return null;
    if (pr.mergeState !== 'CLEAN') return null;
    if (pr.checkConclusion !== 'none' && pr.checkConclusion !== 'pending') return null;
    return pr;
