    ];

    function cliRouteHit(c, route) {
        if (c.indexOf(route.needle) === -1) return false;
        if (route.jq === null) return true;
        return (c.indexOf('--jq') !== -1) === route.jq;
    }

    function cliRouter(map) {
        return function (cmdOpts) {
