{"newText":"// The lifecycle-arm test on the item's labels: approved and/or armed.
function _armedLabels(labels) {
    var list = labels || [];
    return list.indexOf('pr_approved') !== -1 ||
        list.indexOf('ai_validating') !== -1;
}

